window.products.push({"id":214510,"name":"Knowledge Unlimited Inc. The Middle Ages Poster Set of 7","category":"homeandappliances","retail price":48.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/71AAyh+nDWL._AC_SL1000_.jpg","description":"Add a visual dimension to your classroom study of the Middle Ages with this informative poster set. Each of the seven posters in the set focuses on a different aspect of the Middle Ages: The Black Death; The Church; Crafts and Guilds; The Crusades; The Feudal System; Knights; and Literature, Art,and Architecture Each full-color poster has a brief explanation of how the event or system helped define this period.","images":["https://m.media-amazon.com/images/I/71AAyh+nDWL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Knowledge Unlimited Inc.","source_asin":"B076BMKQ4Z","category_path":"Home & Kitchen"},"sku":"BM-214510","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B076BMKQ4Z","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B076BMKQ4Z","price_pending":true,"merchant_ready":false});
